class LayoutSwitcher extends HTMLElement {
  private buttons: NodeListOf<HTMLButtonElement> | null = null;
  private collectionGrid: HTMLElement | null = null;

  constructor() {
    super();
  }

  connectedCallback(): void {
    this.cacheDomElements();
    this.bindEvents();
  }

  private cacheDomElements(): void {
    this.buttons = this.querySelectorAll("button[data-layout]");
    this.collectionGrid = document.querySelector(".collection__grid");
  }

  private bindEvents(): void {
    if (!this.buttons || !this.collectionGrid) {
      return;
    }

    this.buttons.forEach((button) => {
      button.addEventListener("click", this.handleLayoutChange.bind(this));
    });
  }

  private handleLayoutChange(event: Event): void {
    const button = event.currentTarget as HTMLButtonElement;
    const layout = button.getAttribute("data-layout");

    // Re-cache the grid element in case it wasn't available during initial load
    if (!this.collectionGrid) {
      this.collectionGrid = document.querySelector(".collection__grid");
    }

    if (!this.collectionGrid || !layout) {
      return;
    }

    // Remove active state from all buttons
    this.buttons?.forEach((btn) => {
      btn.classList.remove("is-active");
      btn.setAttribute("aria-pressed", "false");
    });

    // Add active state to clicked button
    button.classList.add("is-active");
    button.setAttribute("aria-pressed", "true");

    // Toggle grid layout class based on layout type
    if (layout === "grid-1") {
      this.collectionGrid.classList.add("collection__grid--mobile-1x");
    } else {
      this.collectionGrid.classList.remove("collection__grid--mobile-1x");
    }
  }
}

if (!customElements.get("uwp-layout-switcher")) {
  customElements.define("uwp-layout-switcher", LayoutSwitcher);
}

export default LayoutSwitcher;
